<?php
require __DIR__.'/bootstrap.php';$u=require_user();$uid=(int)$u['id'];
function cart_data(mysqli $db,int $uid):array{$stmt=$db->prepare("SELECT ci.id,p.id product_id,p.slug,p.title,p.price,ci.quantity,pi.image_url image FROM carts c JOIN cart_items ci ON ci.cart_id=c.id JOIN products p ON p.id=ci.product_id LEFT JOIN product_images pi ON pi.product_id=p.id AND pi.is_primary=1 WHERE c.user_id=? ORDER BY ci.added_at DESC");$stmt->bind_param('i',$uid);$items=db_all($stmt);$subtotal=0;foreach($items as &$i){$i['price']=(float)$i['price'];$i['quantity']=(int)$i['quantity'];$subtotal+=$i['price']*$i['quantity'];}return ['items'=>$items,'subtotal'=>$subtotal,'count'=>array_sum(array_column($items,'quantity'))];}
if(method()==='GET')ok(cart_data($db,$uid));$in=input();
if(method()==='POST'){$pid=int_value($in['product_id']??null,'product');$qty=max(1,min(20,(int)($in['quantity']??1)));$stmt=$db->prepare('SELECT id,quantity,status,sale_type FROM products WHERE id=?');$stmt->bind_param('i',$pid);$p=db_one($stmt);if(!$p||$p['status']!=='active'||$p['sale_type']!=='fixed')fail('Product is not available for purchase.',409);if($qty>(int)$p['quantity'])fail('Requested quantity is unavailable.',409);$stmt=$db->prepare('INSERT IGNORE INTO carts(user_id) VALUES(?)');$stmt->bind_param('i',$uid);$stmt->execute();$stmt=$db->prepare('INSERT INTO cart_items(cart_id,product_id,quantity) SELECT id,?,? FROM carts WHERE user_id=? ON DUPLICATE KEY UPDATE quantity=LEAST(20,quantity+VALUES(quantity))');$stmt->bind_param('iii',$pid,$qty,$uid);$stmt->execute();ok(cart_data($db,$uid),'Added to cart.',201);}
if(method()==='PATCH'){$pid=int_value($in['product_id']??null,'product');$qty=(int)($in['quantity']??0);if($qty<1||$qty>20)fail('Quantity must be between 1 and 20.',422);$stmt=$db->prepare('UPDATE cart_items ci JOIN carts c ON c.id=ci.cart_id SET ci.quantity=? WHERE c.user_id=? AND ci.product_id=?');$stmt->bind_param('iii',$qty,$uid,$pid);$stmt->execute();ok(cart_data($db,$uid),'Cart updated.');}
if(method()==='DELETE'){$pid=int_value($in['product_id']??($_GET['product_id']??null),'product');$stmt=$db->prepare('DELETE ci FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.user_id=? AND ci.product_id=?');$stmt->bind_param('ii',$uid,$pid);$stmt->execute();ok(cart_data($db,$uid),'Removed from cart.');}fail('Method not allowed.',405);
